    // Validate the image format.
    if (format < PP_IMAGEDATAFORMAT_BGRA || format > PP_IMAGEDATAFORMAT_RGBA_PREMUL) {
        return false;
    }

    // Validate width and height.
    if (width <= 0 || height <= 0) {
        return false;
    }

    // Ensure that the product of width and height does not overflow int.
    if (width > INT_MAX / height) {
        return false;
    }

    // Initialize the backend with the validated parameters.
    return BackendInit(format, width, height, init_to_zero);
}
